('4506', '56', '44', '43-Chap6', 'Planifier les risques, opportunités et objectifs du SMSI (Méthodologie d''analyse, Registre des risques, Registre des actifs, Plan de traitement, DdA, Objectifs, Plan de communication).', 'SMSI', NULL, 'Gouvernance', 'Document_Cadre', '146', 'RSSI_Gouvernance', 'Continu', 'Critique', NULL, 'Non_traitee', '2026-08-11 03:19:55', '2026-09-07 01:49:56', 'requirement', 'ISO27001', NULL, NULL, '0', NULL, NULL, NULL, 'livrable'),
('4507', '56', '44', '43-Chap7', 'Assurer les ressources, la compétence et la communication nécessaires au SMSI (Plan de gestion des ressources, Plan de formation, Registre de suivi, Procédure de communication, Modèles, Listing des documents externes).', 'SMSI', NULL, 'Gouvernance', 'Document_Cadre', '154', 'RSSI_Gouvernance', 'Continu', 'Majeure', NULL, 'Non_traitee', '2026-08-11 03:19:55', '2026-09-07 01:49:56', 'requirement', 'ISO27001', NULL, NULL, '0', NULL, NULL, NULL, 'livrable'),
